//! Tests of the path engine. The tables hold what a Postgres 16 server answered (a database in
//! C.UTF-8, time zone UTC): jsonb_path_query_array, jsonb_path_exists, jsonb_path_match and the
//! `_tz` functions, `'...'::jsonpath`, and `numeric`'s own arithmetic.
//! `differential` (ignored) runs cases from a file against this code, for checking it with a live
//! server.

use super::*;

fn json(s: &str) -> Json {
    serde_json::from_str(s).unwrap()
}

/// An error's message without the DETAIL and HINT that may follow it (after a `\u{1}` or a `\u{2}`), as the
/// tables hold it.
fn head(msg: &str) -> &str {
    msg.split(['\u{1}', '\u{2}']).next().unwrap_or(msg)
}

fn shown<T: fmt::Debug>(r: Result<T, PathError>, f: impl Fn(T) -> String) -> String {
    match r {
        Ok(v) => f(v),
        Err((code, msg)) => format!("ERR {code} {}", head(&msg)),
    }
}

/// `jsonb_path_query_array`, `jsonb_path_exists` and `jsonb_path_match` of a path over a target,
/// in the words the tables use.
fn answer(target: &str, path: &str, vars: &str, silent: bool) -> [String; 3] {
    let (t, v) = (Value::parse(target).unwrap(), Value::parse(vars).unwrap());
    let p = match parse_code(path) {
        Ok(p) => p,
        Err((code, msg)) => panic!("{path} does not parse: {code} {msg}"),
    };
    let flag = |b: Option<bool>| b.map_or("null".to_string(), |b| b.to_string());
    [
        shown(query_value(&p, &t, &v, silent, false), |items| Value::Array(items).to_string()),
        shown(exists_value(&p, &t, &v, silent, false), flag),
        shown(predicate_value(&p, &t, &v, silent, false), flag),
    ]
}

