/// What this code answers to one differential case (mode `query`, `exists`, `match` or
/// `parse`), in the words `pg_temp.ev` gives Postgres's: `ERR sqlstate message` for an error.
fn diff_answer(mode: &str, target: &str, path: &str, vars: &str, silent: bool, tz: bool) -> String {
    let flag = |b: Option<bool>| b.map_or("NULL".to_string(), |b| b.to_string());
    let err = |(code, msg): PathError| format!("ERR {code} {}", head(&msg));
    let p = match parse_code(path) {
        Ok(p) => p,
        Err(e) => return err(e),
    };
    if mode == "parse" {
        return p.to_string();
    }
    let (t, v) = match (Value::parse(target), Value::parse(vars)) {
        (Ok(t), Ok(v)) => (t, v),
        (Err(e), _) | (_, Err(e)) => return err(e),
    };
    match mode {
        "query" => query_value(&p, &t, &v, silent, tz).map_or_else(err, |i| Value::Array(i).to_string()),
        "exists" => exists_value(&p, &t, &v, silent, tz).map_or_else(err, flag),
        "match" => predicate_value(&p, &t, &v, silent, tz).map_or_else(err, flag),
        _ => panic!("{mode}"),
    }
}

/// Reads `JP_CASES` (a JSON array per line: mode, target, path, vars, silent, tz) and writes
/// what this code answers to `JP_OUT`, a JSON string per line: for differential runs against
/// a live Postgres.
#[test]
#[ignore = "a differential run against a live Postgres, fed by JP_CASES"]
fn differential() {
    let (Ok(cases), Ok(out)) = (std::env::var("JP_CASES"), std::env::var("JP_OUT")) else { return };
    // the session's time zone, in seconds east of UTC
    let zone: i32 = std::env::var("JP_ZONE").ok().and_then(|z| z.parse().ok()).unwrap_or(0);
    let mut res = String::new();
    for line in std::fs::read_to_string(cases).unwrap().lines() {
        let c: Vec<Json> = serde_json::from_str(line).unwrap();
        let s = |i: usize| c[i].as_str().unwrap().to_string();
        // a path that overflows the stack is answered like Postgres's limit: the test thread is small
        let (mode, t, p, v) = (s(0), s(1), s(2), s(3));
        let (silent, tz) = (c[4].as_bool().unwrap(), c[5].as_bool().unwrap());
        let got = std::thread::Builder::new()
            .stack_size(8 << 20)
            .spawn(move || {
                super::super::time::ZONE.set(zone);
                diff_answer(&mode, &t, &p, &v, silent, tz)
            })
            .unwrap()
            .join()
            .unwrap_or_else(|_| "PANIC".to_string());
        res.push_str(&Json::String(got).to_string());
        res.push('\n');
    }
    std::fs::write(out, res).unwrap();
}

#[test]
fn answers_like_postgres() {
    assert!(QUERIES.len() >= 60);
    for (target, path, vars, silent, q, e, m) in QUERIES {
        let got = answer(target, path, vars, *silent);
        let silent = if *silent { " (silent)" } else { "" };
        assert_eq!(got, [q.to_string(), e.to_string(), m.to_string()], "{path}{silent} over {target} with {vars}");
    }
}

#[test]
fn syntax_errors_like_postgres() {
    for (path, code, msg) in SYNTAX {
        assert_eq!(parse_code(path).err(), Some((*code, msg.to_string())), "{path:?}");
        assert_eq!(parse(path).err().as_deref(), Some(*msg), "{path:?}");
    }
}

#[test]
fn paths_print_like_postgres() {
    for (path, text) in TEXTS {
        let parsed = parse(path).unwrap();
        assert_eq!(&parsed.to_string(), text, "{path}");
        // the printed form is a path that means the same, and prints the same
        assert_eq!(&parse(text).unwrap().to_string(), text, "{text}");
    }
}

#[test]
fn silent_hides_what_postgres_hides() {
    let t = json(r#"{"a": [1, 2, 3], "s": "x"}"#);
    let none = json("{}");
    let p = |s: &str| parse(s).unwrap();
    // a missing key in strict mode: an error, unless silent (then exists is NULL, not false)
    assert_eq!(
        exists(&p("strict $.b"), &t, &none, false),
        Err(("2203A", "JSON object does not contain key \"b\"".into()))
    );
    assert_eq!(exists(&p("strict $.b"), &t, &none, true), Ok(None));
    assert_eq!(exists(&p("lax $.b"), &t, &none, false), Ok(Some(false)));
    assert_eq!(query(&p("strict $.a[7]"), &t, &none, true), Ok(vec![]));
    // what was found before a silenced error stays
    assert_eq!(query(&p("strict $.a[*] + 1"), &t, &none, true), Ok(vec![]));
    assert_eq!(query(&p("$.a[*].abs() ? (@ > 0)"), &t, &none, false), Ok(vec![json("1"), json("2"), json("3")]));
    assert_eq!(query(&p("$.s.abs()"), &t, &none, true), Ok(vec![]));
    assert_eq!(query(&p("$.s.abs()"), &t, &none, false).unwrap_err().0, "22036");
    // @@: one boolean, or NULL for unknown; anything else is an error (NULL if silent)
    assert_eq!(predicate(&p("$.a[*] > 2"), &t, &none, false), Ok(Some(true)));
    assert_eq!(predicate(&p("$.s > 2"), &t, &none, false), Ok(None));
    assert_eq!(predicate(&p("$.a[*]"), &t, &none, false), Err(("22038", "single boolean result is expected".into())));
    assert_eq!(predicate(&p("$.a[*]"), &t, &none, true), Ok(None));
    // @?: any item at all
    assert_eq!(exists(&p("$.a[*] ? (@ > 2)"), &t, &none, true), Ok(Some(true)));
    assert_eq!(exists(&p("$.a[*] ? (@ > 3)"), &t, &none, true), Ok(Some(false)));
    // a variable that isn't there, and variables that aren't an object, are errors even when silent
    let missing = Err(("42704", "could not find jsonpath variable \"x\"".to_string()));
    assert_eq!(query(&p("$x"), &t, &none, true), missing);
    let not_object = Err(("22023", "\"vars\" argument is not an object".to_string()));
    assert_eq!(query(&p("$"), &t, &json("[1]"), true), not_object);
    assert_eq!(query(&p("$x"), &t, &json("{\"x\": [1, 2]}"), false), Ok(vec![json("[1, 2]")]));
}

#[test]
fn decimals_match_numeric_digit_for_digit() {
    let dec = |s: &str| Numeric::parse(s).unwrap();
    let text = |d: Result<Numeric, NumError>| d.ok().map(|d| d.to_string());
    for (op, a, b, want) in NUMERIC {
        let got = if *op == "float8" {
            float8(a).and_then(Numeric::from_f64_15).map(|n| n.to_string())
        } else {
            let (x, y) = (dec(a), if b.is_empty() { Numeric::zero() } else { dec(b) });
            match *op {
                "div" => text(x.div(&y)),
                "rem" => text(x.rem(&y)),
                "add" => text(x.add(&y)),
                "sub" => text(x.sub(&y)),
                "mul" => text(x.mul(&y)),
                "floor" => Some(x.floor().to_string()),
                "ceil" => Some(x.ceil().to_string()),
                "len" => Some(x.stored_len().to_string()),
                _ => None, // a division by zero
            }
        };
        assert_eq!(got.as_deref().unwrap_or("NONE"), *want, "{op} {a} {b}");
    }
    assert!(NUMERIC.len() >= 100);
}

#[test]
fn a_path_is_plain_data() {
    fn plain<T: Send + Sync + Clone + fmt::Debug + fmt::Display>() {}
    plain::<Path>();
    let p = parse("strict $.a[*] ? (@ > 1)").unwrap();
    assert_eq!(p.clone().to_string(), p.to_string());
}

#[test]
fn like_regex_flags_reach_the_engine() {
    let run = |path: &str, target: &str| exists(&parse(path).unwrap(), &json(target), &json("{}"), true);
    // `.` and `[^...]` stop at a newline unless flag s; m makes ^ and $ match at lines
    assert_eq!(run("$ ? (@ like_regex \"a.b\")", "\"a\\nb\""), Ok(Some(false)));
    assert_eq!(run("$ ? (@ like_regex \"a.b\" flag \"s\")", "\"a\\nb\""), Ok(Some(true)));
    assert_eq!(run("$ ? (@ like_regex \"a[^x]b\")", "\"a\\nb\""), Ok(Some(false)));
    assert_eq!(run("$ ? (@ like_regex \"a[^x]b\" flag \"s\")", "\"a\\nb\""), Ok(Some(true)));
    assert_eq!(run("$ ? (@ like_regex \"^b\")", "\"a\\nb\""), Ok(Some(false)));
    assert_eq!(run("$ ? (@ like_regex \"^b$\" flag \"m\")", "\"a\\nb\\nc\""), Ok(Some(true)));
    assert_eq!(run("$ ? (@ like_regex \"A.B\" flag \"iq\")", "\"a.b\""), Ok(Some(true)));
    assert_eq!(run("$ ? (@ like_regex \"a.b\" flag \"q\")", "\"axb\""), Ok(Some(false)));
    assert_eq!(run("$ ? (@ like_regex \"a+\\\\d\")", "\"aa1\""), Ok(Some(true)));
    // a pattern that isn't a regular expression fails when the path is read, as in Postgres
    assert_eq!(parse_code("$ ? (@ like_regex \"(\")").unwrap_err().0, "2201B");
    assert_eq!(parse_code("$ ? (@ like_regex \"a\" flag \"x\")").unwrap_err().0, "0A000");
}

#[test]
fn deep_paths_are_answered_or_refused_not_overflowed() {
    // a thread with as small a stack as a test's: what is too deep for it gets a stack of its own
    let ran = std::thread::Builder::new().stack_size(2 << 20).spawn(|| {
        let none = json("{}");
        let q = |path: &str, target: &str| query(&parse(path).unwrap(), &json(target), &none, false);
        // what Postgres takes (it stops at about 1600 nested subscripts and 3300 chained items)
        let fine = "(".repeat(3000) + "$.a" + &")".repeat(3000);
        assert_eq!(q(&fine, r#"{"a": 1}"#), Ok(vec![json("1")]));
        let chain = "$".to_string() + &".a".repeat(5000);
        assert_eq!(q(&chain, "{}"), Ok(vec![]));
        assert_eq!(q(&("lax $".to_string() + &"[0]".repeat(3000)), "5"), Ok(vec![json("5")]));
        assert_eq!(q(&("$".to_string() + &"[*]".repeat(3000)), "[10, 20]"), Ok(vec![json("10"), json("20")]));
        assert_eq!(q(&("$".to_string() + &".**".repeat(300)), "[1]").unwrap().len(), 301);
        assert_eq!(q(&("$".to_string() + &" ? (@ == 1)".repeat(3000)), "1"), Ok(vec![json("1")]));
        assert_eq!(q(&("$ + ".to_string() + &vec!["1"; 4000].join(" + ")), "0"), Ok(vec![json("4000")]));
        assert_eq!(q(&("-".repeat(2000) + "$"), "5"), Ok(vec![json("5")]));
        assert_eq!(q(&("$ ? (".to_string() + &"@ == 1 && ".repeat(3000) + "@ == 1)"), "1"), Ok(vec![json("1")]));
        assert_eq!(
            q(&("$ ? (".to_string() + &"!(".repeat(1000) + "@ == 1" + &")".repeat(1000) + ")"), "1"),
            Ok(vec![json("1")])
        );
        let subs = "$[".to_string() + &vec!["0"; 30000].join(",") + "]";
        assert_eq!(q(&subs, "[7]").unwrap().len(), 30000);
        // what no stack holds is refused, with Postgres's SQLSTATE, and not overflowed
        let deep = [
            "(".repeat(100_000) + "1" + &")".repeat(100_000),
            "-".repeat(100_000) + "1",
            "!(".repeat(50_000) + "1 == 1" + &")".repeat(50_000),
            "$".to_string() + &" ? (@ != 1".repeat(50_000) + &")".repeat(50_000),
            "$".to_string() + &"[0".repeat(50_000) + &"]".repeat(50_000),
        ];
        for path in deep {
            assert_eq!(parse_code(&path).err().map(|e| e.0), Some("54001"), "{}", &path[..20]);
        }
        // and so is data nested as far as jsonb allows
        let mut doc = json("1");
        for _ in 0..100 {
            doc = Json::Array(vec![doc]);
        }
        assert_eq!(query(&parse("$.**").unwrap(), &doc, &none, false).unwrap().len(), 101);
        // a path printed, cloned and dropped on a small stack
        let long = parse(&chain).unwrap();
        assert!(long.to_string().len() > 10_000 && long.clone().to_string() == long.to_string());
    });
    ran.unwrap().join().unwrap();
}

#[test]
fn keyvalue_ids_follow_jsonb_layout() {
    let run = |path: &str, target: &str, vars: &str| {
        let items = query(&parse(path).unwrap(), &json(target), &json(vars), false).unwrap();
        items.iter().map(|i| i["id"].as_i64().unwrap()).collect::<Vec<_>>()
    };
    let doc = r#"{"a": {"b": {"c": 1}}, "d": [{"e": 1}, {"e": 2}]}"#;
    // an object starts on a 4-byte boundary, after its parents' headers, entries, keys and numbers
    assert_eq!(run("$.keyvalue()", doc, "{}"), [0, 0]);
    assert_eq!(run("$.a.keyvalue()", doc, "{}"), [24]);
    assert_eq!(run("$.a.b.keyvalue()", doc, "{}"), [40]);
    assert_eq!(run("$.d[*].keyvalue()", doc, "{}"), [76, 100]);
    // a variable's objects count from the variables (base 1), the ones a method makes from their own
    assert_eq!(run("$x.keyvalue()", "1", r#"{"x": {"a": 1}}"#), [10_000_000_016]);
    assert_eq!(run("$.keyvalue().value.keyvalue()", doc, "{}"), [20_000_000_048, 40_000_000_060, 40_000_000_084]);
}

/// `answer` for any path, target and variables: when one of them is no good, all three answers
/// are the error Postgres gives.
fn answer_with(target: &str, path: &str, vars: &str, silent: bool, tz: bool) -> [String; 3] {
    let broken = |(code, msg): PathError| {
        let e = format!("ERR {code} {}", head(&msg));
        [e.clone(), e.clone(), e]
    };
    let p = match parse_code(path) {
        Ok(p) => p,
        Err(e) => return broken(e),
    };
    let (t, v) = match (Value::parse(target), Value::parse(vars)) {
        (Ok(t), Ok(v)) => (t, v),
        (Err(e), _) | (_, Err(e)) => return broken(e),
    };
    let flag = |b: Option<bool>| b.map_or("null".to_string(), |b| b.to_string());
    [
        shown(query_value(&p, &t, &v, silent, tz), |items| Value::Array(items).to_string()),
        shown(exists_value(&p, &t, &v, silent, tz), flag),
        shown(predicate_value(&p, &t, &v, silent, tz), flag),
    ]
}

